declarative_ui.ui_code:
"use strict";

// Ticket to Ride: Europe (Declarative) presentation.
// Pure ES2020, no DOM, no timers, no randomness, no clock reads.
// gameUI.reduce(message, localState) returns a complete scene snapshot
// and, only for a tap by the current player on a legal action, a
// make_move. The server owns all rules; this code never computes
// winners, payouts or ticket completion. Hidden information: the view
// only ever carries the viewer's own hand and tickets, so nothing can
// leak through the reducer.
//
// The map is a graph board: cities are cells, each route has one cell
// per train space plus a midpoint cell used by its target. Every
// physical train keeps one stable id "train_<seat>_<index>" for the
// whole match: unplaced trains sit in the owner's supply pile on the
// map edge, and claimed routes take the lowest free indices in route
// order, so a newly claimed route's trains slide from the pile onto
// the route. Face-up cards keep their slot ids; the hand is one chip
// per colour with a count (the view exposes colour counts, not card
// identities, so individual hand cards have no stable identity to
// track). Score lines show every player's trains, points, tickets
// and cards in every scene.
//
// Interaction is multi-step and kept in local_state: draw is two taps
// (deck or a face-up card, then a second pick; tapping a face-up first
// pick again cancels, while tapping the deck again draws a second deck
// card — a double deck draw is a core action and cannot be cancelled
// once the first card is taken); claiming is tap a route, then pick a
// colour for grey routes and an extra card for the tunnel, then tap
// Claim; tickets are tap Draw tickets, tap the ones to keep, tap Keep.

var SOURCE_STRINGS = {
  "title": "Ticket to Ride: Europe",
  "waiting_platform": "Waiting for the platform…",
  "replay": "Viewing move {index} of {total} · read only",
  "wins": "{name} wins!",
  "tie": "It's a tie.",
  "over": "The match is over.",
  "your_move": "Your move, {name}.",
  "waiting_for": "Waiting for {names}.",
  "player_label": "{name}",
  "score_line": "{name}: {trains} trains · {points} points · {tickets} tickets · {cards} cards",
  "final_score": "{name}: {score} points",
  "hand_label": "Your hand",
  "tickets_label": "Your tickets",
  "ticket_line": "{from} to {to} · {points} points",
  "card_red": "Red",
  "card_blue": "Blue",
  "card_green": "Green",
  "card_yellow": "Yellow",
  "card_black": "Black",
  "card_white": "White",
  "card_orange": "Orange",
  "card_pink": "Pink",
  "card_loco": "Locomotive",
  "card_count": "{count} × {color}",
  "city_london": "London",
  "city_paris": "Paris",
  "city_madrid": "Madrid",
  "city_berlin": "Berlin",
  "city_vienna": "Vienna",
  "city_rome": "Rome",
  "city_athens": "Athens",
  "city_warsaw": "Warsaw",
  "city_stockholm": "Stockholm",
  "city_amsterdam": "Amsterdam",
  "map_label": "Map of Europe",
  "routes_label": "Routes",
  "route_line": "{from} to {to}",
  "route_detail": "{route} · {color} · {length} spaces · {points} points",
  "route_claimed": "{route} · claimed by {name}",
  "color_grey": "any colour",
  "deck_label": "Deck: {count} cards",
  "discard_label": "Discard pile: {count} cards",
  "faceup_label": "Face-up cards",
  "draw_hint": "Draw two cards: pick from the deck or the face-up cards.",
  "draw_second": "Pick a second card, or tap the first pick again to cancel.",
  "choose_color": "Choose a colour for this route",
  "choose_extra": "Choose the extra tunnel card",
  "claim_confirm": "Claim {route}",
  "tickets_button": "Draw tickets",
  "keep_button": "Keep selected tickets",
  "keep_hint": "Choose at least one ticket to keep.",
  "pass_button": "Pass",
  "final_round": "Final round: {count} turns left",
  "pending_label": "New tickets",
  "moves_label": "Move {count}",
  "server_the_game_is_over": "the game is over",
  "server_send_a_valid_action": "send a valid action",
  "server_you_are_not_in_this_match": "you are not in this match",
  "server_that_move_is_not_allowed": "that move is not allowed",
  "server_you_must_choose_your_tickets_first": "you must choose your tickets first",
  "server_send_one_or_two_cards_to_draw": "send one or two cards to draw",
  "server_you_cannot_draw_that_card": "you cannot draw that card",
  "server_the_deck_is_empty": "the deck is empty",
  "server_a_face_up_locomotive_ends_your_draw": "a face-up locomotive ends your draw",
  "server_send_a_route_from_0_to_13": "send a route from 0 to 13",
  "server_that_route_is_already_claimed": "that route is already claimed",
  "server_send_a_colour_from_0_to_7": "send a colour from 0 to 7",
  "server_that_route_needs_a_different_colour": "that route needs a different colour",
  "server_a_tunnel_needs_one_extra_card": "a tunnel needs one extra card",
  "server_only_a_tunnel_needs_an_extra_card": "only a tunnel needs an extra card",
  "server_you_do_not_have_enough_trains": "you do not have enough trains",
  "server_you_do_not_have_the_cards_for_that_route": "you do not have the cards for that route",
  "server_no_tickets_are_left_to_draw": "no tickets are left to draw",
  "server_there_are_no_tickets_to_choose": "there are no tickets to choose",
  "server_you_must_keep_at_least_one_ticket": "you must keep at least one ticket"
};

// Cities: [x%, y%] of the map board. Routes: [a, b, colour, length, tunnel].
// Colours: 0 red, 1 blue, 2 green, 3 yellow, 4 black, 5 white, 6 orange,
// 7 pink, 8 locomotive (wild), 9 grey (any single colour).
var CITIES = [[18, 22], [30, 45], [22, 72], [55, 32], [62, 52], [58, 74], [72, 82], [68, 22], [58, 8], [42, 22]];
var ROUTES = [
  [0, 1, 1, 2, false], [1, 2, 0, 4, false], [1, 3, 3, 3, false],
  [1, 9, 5, 2, false], [9, 3, 4, 3, false], [3, 7, 2, 4, false],
  [3, 4, 6, 3, false], [4, 5, 7, 3, false], [4, 6, 0, 4, false],
  [5, 6, 1, 4, false], [7, 8, 5, 3, false], [3, 8, 3, 4, true],
  [0, 9, 9, 2, false], [4, 7, 4, 2, false]
];
var TICKETS = [
  [0, 5, 8], [0, 6, 10], [1, 4, 6], [1, 6, 9], [2, 3, 8], [2, 4, 9],
  [3, 6, 9], [3, 5, 6], [9, 6, 10], [9, 5, 7], [8, 5, 9], [8, 2, 11]
];
var ROUTE_POINTS = [0, 1, 2, 4, 7];
// Clockwise degrees of each route's direction (city A to city B).
var ROUTE_ANGLES = [46.8, 118.1, -16.1, -46.8, 23.1, -23.1, 57.8, 108.1, 59.0, 17.6, -142.1, -77.3, 0.0, -70.2];
var MAP_X = 20;
var MAP_Y = 100;
var MAP_W = 720;
var MAP_H = 400;

var gameUI = {
  reduce: function (message, localState) {
    var m = message;
    if (message && message.type === "ui_event") m = message.state_changed;
    var s = null;
    if (m) s = m.view || m.state || null;

    var strings = {};
    var k;
    for (k in SOURCE_STRINGS) strings[k] = SOURCE_STRINGS[k];
    if (m && m.strings) {
      for (k in m.strings) strings[k] = m.strings[k];
    }
    function t(key, params) {
      var text = strings[key] || key;
      return text.replace(/\{(\w+)\}/g, function (match, name) {
        if (params && name in params) return String(params[name]);
        return match;
      });
    }
    function cardName(color) {
      if (color === 0) return t("card_red");
      if (color === 1) return t("card_blue");
      if (color === 2) return t("card_green");
      if (color === 3) return t("card_yellow");
      if (color === 4) return t("card_black");
      if (color === 5) return t("card_white");
      if (color === 6) return t("card_orange");
      if (color === 7) return t("card_pink");
      return t("card_loco");
    }
    function cityName(city) {
      if (city === 0) return t("city_london");
      if (city === 1) return t("city_paris");
      if (city === 2) return t("city_madrid");
      if (city === 3) return t("city_berlin");
      if (city === 4) return t("city_vienna");
      if (city === 5) return t("city_rome");
      if (city === 6) return t("city_athens");
      if (city === 7) return t("city_warsaw");
      if (city === 8) return t("city_stockholm");
      return t("city_amsterdam");
    }
    function playerName(seat) {
      var p = null;
      if (m && m.players && m.players[seat]) p = m.players[seat];
      var nm = null;
      if (p) nm = p.name || p.display_name || null;
      if (!nm) nm = String(seat + 1);
      return t("player_label", { name: nm });
    }
    function routeText(r) {
      var route = ROUTES[r];
      return t("route_line", { from: cityName(route[0]), to: cityName(route[1]) });
    }
    function routeColorName(r) {
      var route = ROUTES[r];
      if (route[2] === 9) return t("color_grey");
      return cardName(route[2]);
    }
    function routeDetail(r) {
      var route = ROUTES[r];
      return t("route_detail", { route: routeText(r), color: routeColorName(r), length: route[3], points: ROUTE_POINTS[route[3]] });
    }
    function cityXY(city) {
      return { x: CITIES[city][0] / 100 * MAP_W, y: CITIES[city][1] / 100 * MAP_H };
    }

    var pieces = [];
    var targets = [];
    var labels = [];
    var controls = [];
    var paths = [];
    labels.push({ id: "title", text: t("title"), x: 20, y: 12, font_size: 26 });

    // Local interaction state, carried across reduce calls.
    var ls = localState || {};
    var firstPick = (ls.firstPick === undefined || ls.firstPick === null) ? null : ls.firstPick;
    var selectedRoute = (ls.selectedRoute === undefined || ls.selectedRoute === null) ? null : ls.selectedRoute;
    var selectedColor = (ls.selectedColor === undefined || ls.selectedColor === null) ? null : ls.selectedColor;
    var selectedExtra = (ls.selectedExtra === undefined || ls.selectedExtra === null) ? null : ls.selectedExtra;
    var keepSel = Array.isArray(ls.keepSel) ? ls.keepSel.slice() : [];

    if (!s) {
      labels.push({ id: "status", text: t("waiting_platform"), x: 20, y: 44, font_size: 20 });
      return { scene: { pieces: pieces, targets: targets, labels: labels, controls: controls, paths: paths }, local_state: {} };
    }

    var mySeat = null;
    if (m && typeof m.my_player_index === "number") mySeat = m.my_player_index;
    var acting = null;
    if (m && typeof m.acting_for_player_index === "number") acting = m.acting_for_player_index;
    var turnSeats = (m && m.turn_of_player_indices) || [];
    var isMyTurn = false;
    var i;
    for (i = 0; i < turnSeats.length; i++) {
      if (turnSeats[i] === mySeat) isMyTurn = true;
    }
    var active = !!(m && m.status === "ongoing" && !m.replay && mySeat !== null && acting !== null && acting === mySeat && isMyTurn);
    var pending = s.pendingTickets !== null && s.pendingTickets !== undefined;
    var over = !!(s.winners && s.winners.length > 0) || m.status === "over";

    var handCounts = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    if (s.hand) {
      for (i = 0; i < s.hand.length; i++) handCounts[s.hand[i]]++;
    }

    // Match the server's payment order: spend the chosen colour first,
    // use locomotives for the remainder, then pay a tunnel's extra card.
    var claimPayments = ROUTES.map(function (route, index) {
      var colors = {};
      if (!active || pending || over || s.claimed[index] !== -1 || s.trains[mySeat] < route[3]) return colors;
      var candidates = route[2] === 9 ? [0, 1, 2, 3, 4, 5, 6, 7] : [route[2]];
      candidates.forEach(function (color) {
        var matching = Math.min(handCounts[color], route[3]);
        var locomotives = route[3] - matching;
        if (locomotives > handCounts[8]) return;
        var extras = [null];
        if (route[4]) {
          extras = [];
          for (var extra = 0; extra < 9; extra++) {
            var used = extra === color ? matching : extra === 8 ? locomotives : 0;
            if (handCounts[extra] > used) extras.push(extra);
          }
        }
        if (extras.length) colors[color] = extras;
      });
      return colors;
    });

    // A new move count invalidates any half-finished selection; pending
    // tickets end the draw/claim flow until the keep is sent.
    if (typeof ls.moves === "number" && ls.moves !== s.moves) {
      firstPick = null;
      selectedRoute = null;
      selectedColor = null;
      selectedExtra = null;
      keepSel = [];
    }
    if (pending) {
      firstPick = null;
      selectedRoute = null;
      selectedColor = null;
      selectedExtra = null;
      keepSel = keepSel.filter(function (idx) { return idx >= 0 && idx < s.pendingTickets.length; });
    }
    if (selectedRoute !== null && !Object.keys(claimPayments[selectedRoute] || {}).length) {
      selectedRoute = null;
      selectedColor = null;
      selectedExtra = null;
    }

    // ---- tap handling (before the scene is built, so the scene reflects
    // the tap immediately): only the acting player, only while ongoing ----
    var makeMove = null;
    if (message && message.type === "ui_event" && active && !m.replay) {
      var ev = message.event;
      if (ev && ev.type === "tap" && typeof ev.id === "string") {
        var id = ev.id;
        var resetSel = function () {
          firstPick = null;
          selectedRoute = null;
          selectedColor = null;
          selectedExtra = null;
          keepSel = [];
        };
        if (pending) {
          if (id.indexOf("pending_") === 0) {
            var pIdx = parseInt(id.slice(8), 10);
            if (pIdx >= 0 && pIdx < s.pendingTickets.length) {
              var at = keepSel.indexOf(pIdx);
              if (at === -1) keepSel.push(pIdx);
              else keepSel.splice(at, 1);
            }
          } else if (id === "keep" && keepSel.length > 0) {
            var keepSorted = keepSel.slice().sort(function (a, b) { return a - b; });
            makeMove = { action: "keep", keep: keepSorted };
            resetSel();
          }
        } else if (id === "deck") {
          if (firstPick === -1) {
            // Tapping the deck again completes a double deck draw
            // (a core Ticket to Ride action); with only one card left
            // there is no second card, so it cancels instead.
            if (s.deckCount > 1) {
              makeMove = { action: "draw", picks: [-1, -1] };
              resetSel();
            } else {
              firstPick = null;
            }
          } else if (firstPick === null) {
            if (s.deckCount > 0) firstPick = -1;
          } else if (s.deckCount > 1) {
            makeMove = { action: "draw", picks: [firstPick, -1] };
            resetSel();
          }
        } else if (id.indexOf("faceup_") === 0) {
          var fIdx = parseInt(id.slice(7), 10);
          if (fIdx >= 0 && fIdx < 5 && s.faceUp[fIdx] !== null && s.faceUp[fIdx] !== undefined) {
            if (firstPick === fIdx) {
              firstPick = null;
            } else if (firstPick === null) {
              if (s.faceUp[fIdx] === 8) {
                makeMove = { action: "draw", picks: [fIdx] };
                resetSel();
              } else {
                firstPick = fIdx;
              }
            } else if (s.faceUp[fIdx] !== 8) {
              makeMove = { action: "draw", picks: [firstPick, fIdx] };
              resetSel();
            }
          }
        } else if (id.indexOf("route_") === 0) {
          var rIdx = parseInt(id.slice(6), 10);
          if (claimPayments[rIdx] && Object.keys(claimPayments[rIdx]).length) {
            if (selectedRoute === rIdx) {
              selectedRoute = null;
              selectedColor = null;
              selectedExtra = null;
            } else {
              selectedRoute = rIdx;
              selectedColor = ROUTES[rIdx][2] === 9 ? null : ROUTES[rIdx][2];
              selectedExtra = null;
            }
          }
        } else if (id.indexOf("color_") === 0 && selectedRoute !== null && ROUTES[selectedRoute][2] === 9) {
          var col = parseInt(id.slice(6), 10);
          if (claimPayments[selectedRoute][col] && selectedColor !== col) {
            selectedColor = col;
            selectedExtra = null;
          }
        } else if (id.indexOf("extra_") === 0 && selectedRoute !== null && ROUTES[selectedRoute][4]) {
          var ex = parseInt(id.slice(6), 10);
          if ((claimPayments[selectedRoute][selectedColor] || []).indexOf(ex) !== -1) selectedExtra = ex;
        } else if (id === "claim" && selectedRoute !== null) {
          var cr = ROUTES[selectedRoute];
          var okClaim = (claimPayments[selectedRoute][selectedColor] || []).indexOf(selectedExtra) !== -1;
          if (okClaim) {
            var mv = { action: "claim", route: selectedRoute, color: selectedColor };
            if (cr[4]) mv.extra = selectedExtra;
            makeMove = mv;
            resetSel();
          }
        } else if (id === "pass") {
          makeMove = { action: "pass" };
          resetSel();
        } else if (id === "tickets") {
          makeMove = { action: "tickets" };
          resetSel();
        }
      }
    }

    // ---- status and hint (each a single t() call, never joined) ----
    var winners = s.winners || [];
    var statusText;
    if (m.replay) {
      statusText = t("replay", { index: m.replay.index, total: m.replay.total });
    } else if (winners.length === 1) {
      statusText = t("wins", { name: playerName(winners[0]) });
    } else if (winners.length > 1) {
      statusText = t("tie");
    } else if (m.status === "over") {
      statusText = t("over");
    } else if (s.finalMoves !== null && s.finalMoves !== undefined) {
      statusText = t("final_round", { count: s.finalMoves });
    } else if (active) {
      statusText = t("your_move", { name: playerName(mySeat) });
    } else {
      var names = [];
      for (i = 0; i < turnSeats.length; i++) names.push(playerName(turnSeats[i]));
      statusText = t("waiting_for", { names: names.join(", ") });
    }
    labels.push({ id: "status", text: statusText, x: 20, y: 44, font_size: 20 });

    var hintText;
    if (pending) {
      hintText = t("keep_hint");
    } else if (selectedRoute !== null) {
      hintText = t("claim_confirm", { route: routeText(selectedRoute) });
    } else if (firstPick !== null) {
      // A deck first pick cannot be cancelled by tapping it again
      // (that now draws the second card), so show the draw hint;
      // a face-up first pick can still be cancelled that way.
      hintText = firstPick === -1 ? t("draw_hint") : t("draw_second");
    } else if (active) {
      hintText = t("draw_hint");
    } else {
      hintText = t("moves_label", { count: s.moves });
    }
    labels.push({ id: "hint", text: hintText, x: 20, y: 72, font_size: 16 });
    labels.push({ id: "map_label", text: t("map_label"), x: 28, y: 106, font_size: 16 });
    labels.push({ id: "routes_label", text: t("routes_label"), x: 620, y: 106, font_size: 16 });

    // ---- map: cities, route paths, trains, route targets ----
    var ROUTE_COLORS = ["#d43d3d", "#3a86ff", "#2a9d5c", "#eab308", "#26221c", "#f2f2f2", "#e8862e", "#e58bb1", "#9a938a"];
    var PLAYER_COLORS = ["#e5484d", "#3a86ff", "#2a9d5c", "#eab308"];
    for (i = 0; i < 10; i++) {
      var cp = cityXY(i);
      pieces.push({
        id: "city_" + i,
        type: "city",
        board: "map",
        position: { cell: "city_" + i },
        aria_label: cityName(i),
        actions: []
      });
      labels.push({ id: "citylabel_" + i, text: cityName(i), x: MAP_X + cp.x + 16, y: MAP_Y + cp.y - 10, font_size: 14 });
    }
    var r;
    for (r = 0; r < ROUTES.length; r++) {
      var ra = cityXY(ROUTES[r][0]);
      var rb = cityXY(ROUTES[r][1]);
      var owner = s.claimed[r];
      paths.push({
        id: "path_" + r,
        points: [{ x: MAP_X + ra.x, y: MAP_Y + ra.y }, { x: MAP_X + rb.x, y: MAP_Y + rb.y }],
        color: owner !== -1 ? PLAYER_COLORS[owner] : (ROUTES[r][2] === 9 ? "#9a938a" : ROUTE_COLORS[ROUTES[r][2]]),
        width: 5
      });
      if (Object.keys(claimPayments[r]).length) {
        targets.push({
          id: "route_" + r,
          board: "map",
          position: { cell: "mid_" + r },
          hit_area: { x: -22, y: -22, width: 44, height: 44 },
          aria_label: routeDetail(r)
        });
      }
    }

    // Trains: stable ids, assigned to claimed routes in route order so a
    // newly claimed route's trains slide from the supply pile.
    var prevClaimed = Array.isArray(ls.claimed) ? ls.claimed : null;
    var newClaims = {};
    if (prevClaimed) {
      for (r = 0; r < ROUTES.length; r++) {
        if (prevClaimed[r] === -1 && s.claimed[r] !== -1) newClaims[r] = true;
      }
    }
    var seat;
    for (seat = 0; seat < s.trains.length; seat++) {
      var assigned = [];
      for (r = 0; r < ROUTES.length; r++) {
        if (s.claimed[r] !== seat) continue;
        for (var k = 0; k < ROUTES[r][3]; k++) assigned.push({ route: r, slot: k });
      }
      for (var ti = 0; ti < 20; ti++) {
        var piece = {
          id: "train_" + seat + "_" + ti,
          type: "train" + seat,
          board: "map",
          actions: []
        };
        if (ti < assigned.length) {
          var asg = assigned[ti];
          piece.position = { cell: "slot_" + asg.route + "_" + asg.slot };
          piece.rotation = ROUTE_ANGLES[asg.route];
          piece.aria_label = t("route_claimed", { route: routeText(asg.route), name: playerName(seat) });
          if (newClaims[asg.route]) {
            if (asg.slot === 0) {
              piece.animation = { kind: "notice", key: "claim-notice-r" + asg.route + "-m" + s.moves, duration_ms: 900 };
            } else {
              piece.animation = { kind: "move", key: "claim-move-r" + asg.route + "-m" + s.moves, duration_ms: 700 };
            }
          }
        } else {
          piece.position = { cell: "supply_" + seat + "_" + ti };
          piece.rotation = 0;
        }
        pieces.push(piece);
      }
    }

    // ---- score lines: one per player, every scene ----
    var nPlayers = 0;
    if (m && m.players) nPlayers = m.players.length;
    if (nPlayers === 0) nPlayers = s.trains.length;
    for (i = 0; i < nPlayers; i++) {
      var scoreText;
      if (over && s.scores && s.scores.length > i) {
        scoreText = t("final_score", { name: playerName(i), score: s.scores[i] });
      } else {
        scoreText = t("score_line", { name: playerName(i), trains: s.trains[i], points: s.points[i], tickets: s.ticketCounts[i], cards: s.handSizes[i] });
      }
      labels.push({ id: "score_" + i, text: scoreText, x: 20, y: 508 + i * 22, font_size: 16 });
    }

    // ---- claim panel labels (separate labels, never joined text) ----
    if (selectedRoute !== null) {
      labels.push({ id: "claim_route", text: routeDetail(selectedRoute), x: 20, y: 596, font_size: 16 });
      var route = ROUTES[selectedRoute];
      if (route[2] === 9 && selectedColor === null) {
        labels.push({ id: "claim_prompt", text: t("choose_color"), x: 380, y: 596, font_size: 16 });
      } else if (route[4] && selectedExtra === null) {
        labels.push({ id: "claim_prompt", text: t("choose_extra"), x: 380, y: 596, font_size: 16 });
      }
    }

    // ---- face-up cards and deck ----
