"use strict";

// Ticket to Ride: Europe for BuildPlay, 2-4 players, simplified.
// A small map of 10 European cities joined by 14 routes. Each player
// starts with 4 train cards, 2 destination tickets and 20 trains. On
// a turn a player draws 2 cards, claims a route, draws 2 more tickets,
// or passes. When a player ends a turn with 2 or fewer trains left,
// every player takes one final turn, then points are counted: route
// points plus completed tickets minus uncompleted tickets. Most points
// wins. This BuildPlay version plays 2 to 4 players (not the 2 to 5 of
// the table game) and omits ferries and train stations; one route is a
// tunnel and costs 1 extra card of any colour.
// Cities: 0 London, 1 Paris, 2 Madrid, 3 Berlin, 4 Vienna, 5 Rome,
// 6 Athens, 7 Warsaw, 8 Stockholm, 9 Amsterdam.
// Colours: 0 red, 1 blue, 2 green, 3 yellow, 4 black, 5 white,
// 6 orange, 7 pink, 8 locomotive (wild), 9 grey (any single colour).
// Routes: [a, b, colour, length, tunnel].
// Tickets: [a, b, points].
// State: { deck, faceUp, discard, ticketsDeck, hands, tickets,
//   pendingTickets, pendingSeat, claimed, trains, points, finalMoves,
//   moves, turnSeat }.
// The deck order, the ticket deck order and other players' hands and
// tickets are hidden: viewFor never includes them.

const CITIES = ["London", "Paris", "Madrid", "Berlin", "Vienna", "Rome", "Athens", "Warsaw", "Stockholm", "Amsterdam"];
const ROUTES = [
  [0, 1, 1, 2, false], // London-Paris, blue, 2
  [1, 2, 0, 4, false], // Paris-Madrid, red, 4
  [1, 3, 3, 3, false], // Paris-Berlin, yellow, 3
  [1, 9, 5, 2, false], // Paris-Amsterdam, white, 2
  [9, 3, 4, 3, false], // Amsterdam-Berlin, black, 3
  [3, 7, 2, 4, false], // Berlin-Warsaw, green, 4
  [3, 4, 6, 3, false], // Berlin-Vienna, orange, 3
  [4, 5, 7, 3, false], // Vienna-Rome, pink, 3
  [4, 6, 0, 4, false], // Vienna-Athens, red, 4
  [5, 6, 1, 4, false], // Rome-Athens, blue, 4
  [7, 8, 5, 3, false], // Warsaw-Stockholm, white, 3
  [3, 8, 3, 4, true],  // Berlin-Stockholm, yellow, 4, tunnel
  [0, 9, 9, 2, false], // London-Amsterdam, grey, 2
  [4, 7, 4, 2, false]  // Vienna-Warsaw, black, 2
];
const TICKETS = [
  [0, 5, 8],  // London-Rome 8
  [0, 6, 10], // London-Athens 10
  [1, 4, 6],  // Paris-Vienna 6
  [1, 6, 9],  // Paris-Athens 9
  [2, 3, 8],  // Madrid-Berlin 8
  [2, 4, 9],  // Madrid-Vienna 9
  [3, 6, 9],  // Berlin-Athens 9
  [3, 5, 6],  // Berlin-Rome 6
  [9, 6, 10], // Amsterdam-Athens 10
  [9, 5, 7],  // Amsterdam-Rome 7
  [8, 5, 9],  // Stockholm-Rome 9
  [8, 2, 11]  // Stockholm-Madrid 11
];
const ROUTE_POINTS = [0, 1, 2, 4, 7];
const START_TRAINS = 20;
const START_CARDS = 4;
const START_TICKETS = 2;
const FACE_UP = 5;
const MAX_MOVES = 150;

function hashContext(ctx, tag) {
  const s = ctx.players.map(function (p) { return p.id; }).join(",") + "|" + ctx.pot + "|" + ctx.players.length + "|" + tag;
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h;
}

function shuffled(items, ctx, tag) {
  const arr = items.slice();
  let s = (hashContext(ctx, tag) % 2147483647) + 1;
  function next() {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return s / 4294967296;
  }
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(next() * (i + 1));
    const tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
  }
  return arr;
}

function newDeck(ctx) {
  const deck = [];
  for (let c = 0; c < 8; c++) {
    for (let k = 0; k < 8; k++) deck.push(c);
  }
  for (let k = 0; k < 8; k++) deck.push(8);
  return shuffled(deck, ctx, "deck");
}

function newTicketDeck(ctx) {
  const tickets = [];
  for (let i = 0; i < TICKETS.length; i++) tickets.push(i);
  return shuffled(tickets, ctx, "tickets");
}

function countCards(hand) {
  const counts = [];
  for (let c = 0; c < 9; c++) counts.push(0);
  for (let i = 0; i < hand.length; i++) counts[hand[i]]++;
  return counts;
}

// Remove one card of the given colour from hand (a copy); returns the
// new hand or null when the colour is not held.
function takeCard(hand, colour) {
  const idx = hand.indexOf(colour);
  if (idx === -1) return null;
  const next = hand.slice();
  next.splice(idx, 1);
  return next;
}

// Can this hand pay for route r in colour c, with extra colour e
// (null when the route is not a tunnel)? Returns the spent hand or null.
function payFor(hand, r, c, e) {
  const route = ROUTES[r];
  const length = route[3];
  const counts = countCards(hand);
  const useColour = Math.min(counts[c], length);
  const useLoco = length - useColour;
  if (useLoco > counts[8]) return null;
  let spent = hand.slice();
  for (let k = 0; k < useColour; k++) spent = takeCard(spent, c);
  for (let k = 0; k < useLoco; k++) spent = takeCard(spent, 8);
  if (spent === null) return null;
  if (route[4]) {
    if (e === null || e === undefined) return null;
    const extra = takeCard(spent, e);
    if (extra === null) return null;
    spent = extra;
  }
  return spent;
}

function canClaim(hand, r, c, e) {
  const route = ROUTES[r];
  if (route[2] !== 9 && c !== route[2]) return false;
  if (route[2] === 9 && (c < 0 || c > 7)) return false;
  if (route[4] && (e === null || e === undefined || e < 0 || e > 8)) return false;
  if (!route[4] && e !== null && e !== undefined) return false;
  return payFor(hand, r, c, e) !== null;
}

// Is ticket t completed by this player's claimed routes?
function ticketDone(claimed, seat, t) {
  const ticket = TICKETS[t];
  const target = ticket[1];
  const seen = [];
  for (let i = 0; i < CITIES.length; i++) seen.push(false);
  const stack = [ticket[0]];
  seen[ticket[0]] = true;
  while (stack.length > 0) {
    const city = stack.pop();
    if (city === target) return true;
    for (let r = 0; r < ROUTES.length; r++) {
      if (claimed[r] !== seat) continue;
      const a = ROUTES[r][0];
      const b = ROUTES[r][1];
      let other = -1;
      if (a === city) other = b;
      else if (b === city) other = a;
      if (other >= 0 && !seen[other]) {
        seen[other] = true;
        stack.push(other);
      }
    }
  }
  return false;
}

function finalScores(state) {
  const scores = [];
  for (let seat = 0; seat < state.trains.length; seat++) {
    let score = state.points[seat];
    for (let k = 0; k < state.tickets[seat].length; k++) {
      const t = state.tickets[seat][k];
      if (ticketDone(state.claimed, seat, t)) score += TICKETS[t][2];
      else score -= TICKETS[t][2];
    }
    scores.push(score);
  }
  return scores;
}

function winnersOfScores(scores) {
  let best = -Infinity;
  for (let i = 0; i < scores.length; i++) {
    if (scores[i] > best) best = scores[i];
  }
  const winners = [];
  for (let i = 0; i < scores.length; i++) {
    if (scores[i] === best) winners.push(i);
  }
  return winners;
}

function endPayouts(state, ctx) {
  const humans = ctx.players.filter(function (p) { return p.kind === "human"; });
  if (humans.length === 0) return {};
  const scores = finalScores(state);
  const winners = winnersOfScores(scores);
  const humanWinners = [];
  for (let i = 0; i < winners.length; i++) {
    if (ctx.players[winners[i]] && ctx.players[winners[i]].kind === "human") {
      humanWinners.push(ctx.players[winners[i]]);
    }
  }
  const recipients = humanWinners.length > 0 ? humanWinners : humans;
  const payouts = {};
  for (let i = 0; i < humans.length; i++) payouts[humans[i].id] = 0;
  const share = Math.floor(ctx.pot / recipients.length);
  for (let i = 0; i < recipients.length; i++) {
    payouts[recipients[i].id] =
      share + (i < ctx.pot - share * recipients.length ? 1 : 0);
  }
  return payouts;
}

function isOver(state) {
  return state.finalMoves !== null && state.finalMoves <= 0;
}

// Every legal move for seat in this state. Used by randomMove and
// computerMove so the generators can never disagree with applyMove.
function legalMoves(state, seat) {
  const moves = [];
  const hand = state.hands[seat];
  if (state.pendingTickets !== null) {
    const n = state.pendingTickets.length;
    const keep = [];
    for (let k = 0; k < n; k++) keep.push(k);
    moves.push({ action: "keep", keep: keep });
    if (n > 1) {
      for (let k = 0; k < n; k++) moves.push({ action: "keep", keep: [k] });
    }
    return moves;
  }
  // Draw: first pick from the deck or a face-up card; a face-up
  // locomotive taken first ends the draw.
  const firstPicks = [];
  if (state.deck.length > 0) firstPicks.push(-1);
  for (let i = 0; i < FACE_UP; i++) {
    if (state.faceUp[i] !== null) firstPicks.push(i);
  }
  for (let a = 0; a < firstPicks.length; a++) {
    const first = firstPicks[a];
    if (first >= 0 && state.faceUp[first] === 8) {
      moves.push({ action: "draw", picks: [first] });
      continue;
    }
    const secondPicks = [];
    // A second deck draw needs 2 deck cards: one for the first pick's
    // draw or refill, one for the second draw itself.
    if (state.deck.length > 1) secondPicks.push(-1);
    for (let i = 0; i < FACE_UP; i++) {
      if (state.faceUp[i] !== null && i !== first && state.faceUp[i] !== 8) secondPicks.push(i);
    }
    for (let b = 0; b < secondPicks.length; b++) {
      moves.push({ action: "draw", picks: [first, secondPicks[b]] });
    }
    if (secondPicks.length === 0) moves.push({ action: "draw", picks: [first] });
  }
  // Claim: every unclaimed route the hand can pay for.
  for (let r = 0; r < ROUTES.length; r++) {
    if (state.claimed[r] !== -1) continue;
    if (state.trains[seat] < ROUTES[r][3]) continue;
    const route = ROUTES[r];
    const colours = route[2] === 9 ? [0, 1, 2, 3, 4, 5, 6, 7] : [route[2]];
    for (let ci = 0; ci < colours.length; ci++) {
      const c = colours[ci];
      if (!route[4]) {
        if (canClaim(hand, r, c, null)) moves.push({ action: "claim", route: r, color: c });
      } else {
        for (let e = 0; e < 9; e++) {
          if (canClaim(hand, r, c, e)) moves.push({ action: "claim", route: r, color: c, extra: e });
        }
      }
    }
  }
  // Draw tickets, when any are left.
  if (state.ticketsDeck.length > 0) moves.push({ action: "tickets" });
  // Passing is always legal, so a player is never stuck.
  moves.push({ action: "pass" });
  return moves;
}

// Score a legal move for the computer: completing a ticket is best,
// then route points, then drawing tickets, then drawing cards.
function scoreMove(state, seat, move) {
  if (move.action === "claim") {
    const route = ROUTES[move.route];
    let score = ROUTE_POINTS[route[3]] * 10;
    const claimed = state.claimed.slice();
    claimed[move.route] = seat;
    for (let k = 0; k < state.tickets[seat].length; k++) {
      const t = state.tickets[seat][k];
      if (!ticketDone(state.claimed, seat, t) && ticketDone(claimed, seat, t)) {
        score += TICKETS[t][2] * 10;
      }
    }
    if (state.trains[seat] - route[3] <= 2) score += 5;
    return score;
  }
  if (move.action === "tickets") return 30;
  if (move.action === "draw") return 20;
  if (move.action === "keep") return 100;
  return 0;
}

const game = {
  newMatch: function (ctx) {
    const deck = newDeck(ctx);
    const ticketsDeck = newTicketDeck(ctx);
    const hands = [];
    const tickets = [];
    for (let seat = 0; seat < ctx.players.length; seat++) {
      hands.push(deck.slice(seat * START_CARDS, seat * START_CARDS + START_CARDS));
      tickets.push(ticketsDeck.slice(seat * START_TICKETS, seat * START_TICKETS + START_TICKETS));
    }
    const usedCards = ctx.players.length * START_CARDS;
    const usedTickets = ctx.players.length * START_TICKETS;
    const faceUp = deck.slice(usedCards, usedCards + FACE_UP);
    return {
      state: {
        deck: deck.slice(usedCards + FACE_UP),
        faceUp: faceUp,
        discard: [],
        ticketsDeck: ticketsDeck.slice(usedTickets),
        hands: hands,
        tickets: tickets,
        pendingTickets: null,
        pendingSeat: null,
        claimed: ROUTES.map(function () { return -1; }),
        trains: ctx.players.map(function () { return START_TRAINS; }),
        points: ctx.players.map(function () { return 0; }),
        finalMoves: null,
        moves: 0,
        turnSeat: 0
      },
      turn: [ctx.players[0].id]
    };
  },

  applyMove: function (state, playerId, move, ctx) {
    if (isOver(state) || state.moves >= MAX_MOVES) throw new InvalidMove("the game is over");
    if (!move || typeof move !== "object" || typeof move.action !== "string") {
      throw new InvalidMove("send a valid action");
    }
    const seat = ctx.players.findIndex(function (p) { return p.id === playerId; });
    if (seat === -1) throw new InvalidMove("you are not in this match");
    if (seat !== state.turnSeat) throw new InvalidMove("that move is not allowed");
    const n = ctx.players.length;
    const nextSeat = (seat + 1) % n;

    // While tickets are pending, only the keep move is allowed.
    if (state.pendingTickets !== null && move.action !== "keep") {
      throw new InvalidMove("you must choose your tickets first");
    }

    const next = JSON.parse(JSON.stringify(state));
    next.moves = state.moves + 1;

    if (move.action === "draw") {
      if (!Array.isArray(move.picks) || move.picks.length < 1 || move.picks.length > 2) {
        throw new InvalidMove("send one or two cards to draw");
      }
      const first = move.picks[0];
      if (first !== -1 && (!Number.isInteger(first) || first < 0 || first >= FACE_UP || state.faceUp[first] === null)) {
        throw new InvalidMove("you cannot draw that card");
      }
      if (first === -1 && state.deck.length === 0) throw new InvalidMove("the deck is empty");
      const firstIsLoco = first >= 0 && state.faceUp[first] === 8;
      if (firstIsLoco && move.picks.length !== 1) {
        throw new InvalidMove("a face-up locomotive ends your draw");
      }
      if (move.picks.length === 2) {
        const second = move.picks[1];
        if (second !== -1 && (!Number.isInteger(second) || second < 0 || second >= FACE_UP || state.faceUp[second] === null || second === first)) {
          throw new InvalidMove("you cannot draw that card");
        }
        if (second >= 0 && state.faceUp[second] === 8) {
          throw new InvalidMove("a face-up locomotive ends your draw");
        }
        if (second === -1 && state.deck.length < 2) {
          throw new InvalidMove("the deck is empty");
        }
      }
      // Draw the cards, refilling face-up slots from the deck.
      for (let k = 0; k < move.picks.length; k++) {
        const pick = move.picks[k];
        if (pick === -1) {
          next.hands[seat].push(next.deck.shift());
        } else {
          next.hands[seat].push(next.faceUp[pick]);
          next.faceUp[pick] = next.deck.length > 0 ? next.deck.shift() : null;
        }
      }
    } else if (move.action === "claim") {
      if (!Number.isInteger(move.route) || move.route < 0 || move.route >= ROUTES.length) {
        throw new InvalidMove("send a route from 0 to 13");
      }
      if (state.claimed[move.route] !== -1) throw new InvalidMove("that route is already claimed");
      if (!Number.isInteger(move.color) || move.color < 0 || move.color > 7) {
        throw new InvalidMove("send a colour from 0 to 7");
      }
      const route = ROUTES[move.route];
      if (route[2] !== 9 && move.color !== route[2]) {
        throw new InvalidMove("that route needs a different colour");
      }
      if (route[4] && (move.extra === null || move.extra === undefined || !Number.isInteger(move.extra) || move.extra < 0 || move.extra > 8)) {
        throw new InvalidMove("a tunnel needs one extra card");
      }
      if (!route[4] && move.extra !== null && move.extra !== undefined) {
        throw new InvalidMove("only a tunnel needs an extra card");
      }
      if (state.trains[seat] < route[3]) throw new InvalidMove("you do not have enough trains");
      const spent = payFor(state.hands[seat], move.route, move.color, route[4] ? move.extra : null);
      if (spent === null) throw new InvalidMove("you do not have the cards for that route");
      // Discard the spent cards, keeping count of colours for the view.
      const countsBefore = countCards(state.hands[seat]);
      const countsAfter = countCards(spent);
      for (let c = 0; c < 9; c++) {
        for (let k = 0; k < countsBefore[c] - countsAfter[c]; k++) next.discard.push(c);
      }
      next.hands[seat] = spent;
      next.claimed[move.route] = seat;
      next.trains[seat] -= route[3];
      next.points[seat] += ROUTE_POINTS[route[3]];
      if (next.finalMoves === null && next.trains[seat] <= 2) {
        next.finalMoves = n;
      }
    } else if (move.action === "tickets") {
      if (state.ticketsDeck.length === 0) throw new InvalidMove("no tickets are left to draw");
      next.pendingTickets = next.ticketsDeck.splice(0, Math.min(2, next.ticketsDeck.length));
      next.pendingSeat = seat;
    } else if (move.action === "keep") {
      if (state.pendingTickets === null) throw new InvalidMove("there are no tickets to choose");
      if (!Array.isArray(move.keep) || move.keep.length < 1 || move.keep.length > state.pendingTickets.length) {
        throw new InvalidMove("you must keep at least one ticket");
      }
      for (let k = 0; k < move.keep.length; k++) {
        const idx = move.keep[k];
        if (!Number.isInteger(idx) || idx < 0 || idx >= state.pendingTickets.length) {
          throw new InvalidMove("you must keep at least one ticket");
        }
      }
      const kept = [];
      const returned = [];
      for (let k = 0; k < state.pendingTickets.length; k++) {
        if (move.keep.indexOf(k) !== -1) kept.push(state.pendingTickets[k]);
        else returned.push(state.pendingTickets[k]);
      }
      next.tickets[seat] = next.tickets[seat].concat(kept);
      next.ticketsDeck = next.ticketsDeck.concat(returned);
      next.pendingTickets = null;
      next.pendingSeat = null;
    } else if (move.action === "pass") {
      // No state change besides the move count and the turn.
    } else {
      throw new InvalidMove("send a valid action");
    }

    // The tickets move does not pass the turn: the same player must keep.
    const passesTurn = move.action !== "tickets";
    if (passesTurn) next.turnSeat = nextSeat;
    if (passesTurn && next.finalMoves !== null) next.finalMoves -= 1;
    const over = (next.finalMoves !== null && next.finalMoves <= 0) || next.moves >= MAX_MOVES;
    const result = {
      state: next,
      turn: over ? null : [ctx.players[passesTurn ? nextSeat : seat].id]
    };
    if (over) result.payouts = endPayouts(next, ctx);
    return result;
  },

  computerMove: function (state, playerId, ctx) {
    const seat = ctx.players.findIndex(function (p) { return p.id === playerId; });
    const moves = legalMoves(state, seat);
    let best = null;
    let bestScore = -Infinity;
    for (let i = 0; i < moves.length; i++) {
      const s = scoreMove(state, seat, moves[i]);
      if (s > bestScore) {
        bestScore = s;
        best = moves[i];
      }
    }
    return best;
  },

  randomMove: function (state, playerId, ctx) {
    const seat = ctx.players.findIndex(function (p) { return p.id === playerId; });
    const moves = legalMoves(state, seat);
    return moves[Math.floor(ctx.random() * moves.length)];
  },

  viewFor: function (state, playerId, ctx) {
    const seat = playerId === null ? -1 : ctx.players.findIndex(function (p) { return p.id === playerId; });
    const over = isOver(state) || state.moves >= MAX_MOVES;
    const scores = over ? finalScores(state) : [];
    const winners = over ? winnersOfScores(scores) : [];
    const view = {
      deckCount: state.deck.length,
      faceUp: state.faceUp.slice(),
      discardCount: state.discard.length,
      hand: seat === -1 ? null : state.hands[seat].slice(),
      handSizes: state.hands.map(function (h) { return h.length; }),
      tickets: seat === -1 ? null : state.tickets[seat].slice(),
      ticketCounts: state.tickets.map(function (t) { return t.length; }),
      pendingTickets: seat >= 0 && state.pendingTickets !== null && state.pendingSeat === seat ? state.pendingTickets.slice() : null,
      claimed: state.claimed.slice(),
      trains: state.trains.slice(),
      points: state.points.slice(),
      finalMoves: state.finalMoves,
      moves: state.moves,
      winners: winners,
      scores: scores
    };
    return view;
  }
};
